def __init__(self, client: UIAutomaCoreClient) -> None:
    self._client = client

def _ensure_open(self) -> None:
    if self._client._closed:
        raise HostUnavailableError("元素对象所属连接已关闭，请重新获取对象")

def _web_target_params(self) -> dict[str, Any]:
    return {"locator_kind": "runtime_ref"}

def _locate_web_element(self, element_id: str, *, timeout_ms: int) -> LocateResult:
    self._ensure_open()
    return self._client._run_web_locate(element_id, timeout_ms=timeout_ms, **self._web_target_params())

def _run_web_action(self, method: str, element_id: str, **params: Any) -> ActionResult:
    self._ensure_open()
    return self._client._run_web_action(method, element_id, **self._web_target_params(), **params)

def _run_web_action(
    self,
    method: str,
    element_id: str,
    **params: Any,
) -> ActionResult:
    self._ensure_method_supported(method)
    rpc_params = {
        "element_id": element_id,
        **params,
    }
    if "timeout_ms" in rpc_params:
        rpc_params["timeout_ms"] = int(rpc_params["timeout_ms"])
    result = self._rpc(method, rpc_params)
    if _business_error(result) != 0 and _trace_info(result) in _FATAL_ACTION_TRACES:
        self._raise_business_error(result, method=method)
    return ActionResult.from_payload(result)

def sleep_after(delay_after: float | int | None) -> None:
    """按动作参数语义在动作后等待。"""

    if delay_after in (None, 0):
        return
    try:
        value = float(delay_after)
    except (TypeError, ValueError) as exc:
        raise InvalidParamsError("delay_after 必须是数字") from exc
    if value < 0:
        raise InvalidParamsError("delay_after 不能小于 0")
    if value:
        time.sleep(value)

def web_highlight_element(self, params: dict[str, Any]) -> dict[str, Any]:
    duration_ms = params.get("duration_ms", 1000)
    timeout_ms = params.get("timeout_ms", 5000)
    if (not isinstance(duration_ms, int) or isinstance(duration_ms, bool) or duration_ms < 0
            or not isinstance(timeout_ms, int) or isinstance(timeout_ms, bool) or timeout_ms <= 0):
        return _action_result(business_error(2, "invalid_params", message="高亮持续时间必须为非负数，定位超时必须大于 0"))
    ctx, err = self._resolve_web_ctx(params)
    if err is not None:
        return _action_result(err)
    if ctx.get("locator_kind") != "runtime_ref":
        return _action_result(business_error(2, "invalid_params", message="请先查找当前网页元素"))
    desc, err = self._web_descriptor(ctx)
    if err is not None:
        return _action_result(err)
    try:
        # The Provider action path activates the target and resolves the live
        # node. Its physical coordinates must not be scaled in Runtime.
        raw = self._web_physical_geometry(desc, timeout_ms, read_geometry=False)
        if _web_bridge_error(raw):
            return _action_result(_web_business_error(_web_bridge_error(raw),
                _trace_from_result(raw, "web_locate_failed"), raw), strategy="web_highlight")
        physical = raw.get("screen_rect")
        rect = _coerce_rect(physical) if isinstance(physical, dict) else None
        if raw.get("count", 1) != 1:
            return _action_result(business_error(4, "ambiguous_match", message="无法确定唯一的网页元素"))
        if rect is None or physical.get("coordinate_space") != "screen_physical":
            return _action_result(business_error(5, "browser_viewport_conversion_failed", message="无法获取网页元素的高亮位置"))
        ok, logs = self.highlighter.highlight(rect, duration_ms / 1000)
        return _action_result(business_error(0, "") if ok else
            business_error(5, "highlight_failed", message="网页元素高亮失败"),
            strategy="web_highlight", log_lines=logs)
    except Exception as exc:
        return _action_result(business_error(5, "highlight_failed", message="网页元素高亮失败"),
            strategy="web_highlight", log_lines=[str(exc)])

def _web_physical_geometry(self, desc: dict[str, Any], timeout_ms: int, *, read_geometry: bool = True) -> dict[str, Any]:
