fn resolve_web_element_with_activation(
    params: Value,
    web_probe: &mut dyn WebProbeClient,
    activate: impl FnOnce(isize) -> bool,
) -> Value {
    let started = Instant::now();
    let failure = |trace: &str| web_validation_failure(5, trace, "无法定位网页元素", None);
    if !params.get("element_ref").is_some_and(Value::is_object)
        || !params
            .get("targetTabId")
            .and_then(Value::as_u64)
            .is_some_and(|id| id > 0)
        || !params
            .get("targetSessionId")
            .and_then(Value::as_str)
            .is_some_and(|id| !id.trim().is_empty())
    {
        return failure("invalid_params");
    }
    let timeout_ms = params
        .get("timeout_ms")
        .and_then(Value::as_u64)
        .unwrap_or(5000)
        .clamp(1, 60000);
    let read_geometry = params.get("read_geometry").and_then(Value::as_bool) == Some(true);
    let mut command = params;
    command["rootHwnd"] = json!(0);
    command["rootPid"] = json!(0);
    command["captureSessionId"] = json!(capture_session_id(None));
    command["action"] = json!(if read_geometry { "geometry" } else { "locate" });
    command["scrollIntoView"] = json!(!read_geometry);
    command["timeoutMs"] = json!(timeout_ms);
    let result = match execute_web_validation_probe(web_probe, &command, timeout_ms) {
        Ok(result) => result,
        Err(_) => return failure("web_bridge_unavailable"),
    };
    if value_as_i64(result.get("error")).unwrap_or(5) != 0 {
        return result;
    }
    let Some(root_hwnd) = result
        .get("provider_root_hwnd")
        .and_then(Value::as_i64)
        .filter(|hwnd| *hwnd > 0)
    else {
        return failure("browser_host_window_mismatch");
    };
    if !read_geometry && !activate(root_hwnd as isize) {
        return web_validation_failure(
            5,
            "browser_window_activation_failed",
            "无法激活浏览器窗口，已取消操作",
            None,
        );
    }
    let remaining = Duration::from_millis(timeout_ms)
        .saturating_sub(started.elapsed()).as_millis() as u64;
    let (mut result, geometry) = match execute_web_validation_with_viewport(
        web_probe, &command, remaining, Some(result),
        |evidence| resolve_browser_viewport_geometry(root_hwnd as HWND, evidence),
    ) {
        Ok(result) => result,
        Err(WebValidationAttemptError::Probe(_)) => return failure("web_bridge_unavailable"),
        Err(WebValidationAttemptError::Viewport(trace)) => return failure(trace),
    };
    if value_as_i64(result.get("error")).unwrap_or(5) != 0 {
        return result;
    }
    if result.get("provider_root_hwnd").and_then(Value::as_i64) != Some(root_hwnd) {
        return failure("browser_host_window_mismatch");
    }
    let Some(geometry) = geometry else {
        return failure("browser_viewport_evidence_missing");
    };
    let Some(evidence) = first_web_validation_evidence(&result) else {
        return failure("web_viewport_evidence_missing");
    };
    if convert_web_validation_result_to_screen(&mut result, geometry) == 0 {
        return failure("browser_viewport_conversion_failed");
    }
    let mut response = json!({"error": 0, "ok": true, "found": true, "count": 1,
        "screen_rect": result["screen_rect"], "strategy": "provider_web_dom"});
    if read_geometry {
        let dpi = unsafe { windows_sys::Win32::UI::HiDpi::GetDpiForWindow(root_hwnd as HWND) };
        let mut client_origin = POINT { x: 0, y: 0 };
        if dpi == 0 || unsafe { ClientToScreen(root_hwnd as HWND, &mut client_origin) } == 0 {
            return failure("browser_viewport_conversion_failed");
        }
        response["window_dpi"] = json!(dpi);
        response["window_client_origin"] = json!({"x": client_origin.x, "y": client_origin.y});
        response["viewport_origin"] = json!({"x": geometry.origin.0, "y": geometry.origin.1});
        response["css_scale"] = json!(evidence.scale);
    }
    response
}

