fn activate_hwnd(hwnd: HWND) -> WndActivationResult {
    let mut result = WndActivationResult::default();
    if hwnd.is_null() {
        return result;
    }

    unsafe {
        if IsWindow(hwnd) == 0 {
            return result;
        }

        let root = {
            let candidate = GetAncestor(hwnd, GA_ROOT);
            if candidate.is_null() { hwnd } else { candidate }
        };
        if root.is_null() || IsWindow(root) == 0 {
            return result;
        }
        if IsIconic(root) == 0 && is_foreground_root(root) {
            result.succeeded = true;
            result.already_foreground = true;
            return result;
        }

        if IsIconic(root) != 0 {
            let restore_started = Instant::now();
            result.restored = true;
            ShowWindow(root, SW_RESTORE);
            for _ in 0..10 {
                if IsIconic(root) == 0 {
                    break;
                }
                thread::sleep(Duration::from_millis(20));
            }
            result.restore = restore_started.elapsed();
            if IsIconic(root) != 0 {
                return result;
            }
        }

        let foreground_started = Instant::now();
        BringWindowToTop(root);
        SetForegroundWindow(root);
